-- REPETITION (lecture seule) -- genere par phase2/checks/famille2_parts_et_ventes_generer_patch_2026-11-27.py (son mot du 27/11)
select (select string_agg(app_affaire_id || '=' || coalesce(vente_reglee_app, '-') || ' / ' || coalesce(numero_facture_app, '-'), ' ; ' order by app_affaire_id) from public.app_affaire_ledger where app_affaire_id in (19133, 27714, 1029, 24620, 4783, 17770)) as les_6_ventes,
  (select string_agg(app_chaine_id || ' ' || cote || ' ' || hektor_user_id || ' ' || nom_au_moment || ' ' || pourcentage || ' ' || origine, ' + ' order by app_chaine_id, cote) from public.app_affaire_repartition where app_chaine_id in (27712, 17769, 24618, 4781)) as les_4_chaines,
  (select count(*) from public.app_affaire_repartition where app_chaine_id in (27712, 17769, 24618, 4781) and coalesce(origine, '') like 'hektor%') as parts_hektor_attendu_0,
  (select count(*) from public.app_classeur_realignement_journal where lot in ('parts_famille2_2026-11-27', 'ventes_reglees_famille2_2026-11-27')) as journal_attendu_20,
  (select count(*) from public.app_affaire_repartition_mise_de_cote where mise_de_cote_par = 'patch_famille2_2026-11-27') as mise_de_cote_attendu_8,
  (select count(distinct l.app_chaine_id) from public.app_affaire_ledger l where l.kind = 'vente' and coalesce(l.vente_reglee_app, '') <> '' and l.app_chaine_id is not null and not exists (select 1 from public.app_affaire_repartition r where r.app_chaine_id = l.app_chaine_id)) as ventes_reglees_sans_part_attendu_0,
  (select count(distinct l.app_chaine_id) from public.app_affaire_ledger l where l.kind = 'vente' and coalesce(l.vente_reglee_app, '') <> '' and exists (select 1 from public.app_affaire_repartition r where r.app_chaine_id = l.app_chaine_id) and not exists (select 1 from public.app_affaire_repartition r where r.app_chaine_id = l.app_chaine_id and coalesce(r.origine, '') not like 'hektor%')) as reglees_sur_supposition_seule_attendu_20,
  (select count(*) from public.app_affaire_repartition r where not exists (select 1 from public.app_affaire_ledger l where l.app_chaine_id = r.app_chaine_id)) as orphelines_attendu_0,
  md5((select md5(coalesce(string_agg(concat_ws('|', app_chaine_id, cote, rang, hektor_user_id, nom_au_moment, pourcentage, origine, ecrit_par), ';' order by app_chaine_id, cote, rang), '')) from public.app_affaire_repartition) || (select md5(coalesce(string_agg(concat_ws('|', app_affaire_id, kind, state, app_chaine_id, app_dossier_numero, coalesce(vente_reglee_app, '-'), coalesce(numero_facture_app, '-'), coalesce(date_annulation_app, '-'), coalesce(motif_annulation_app, '-'), coalesce(honoraires_entree_app::text, '-')), ';' order by app_affaire_id), '')) from public.app_affaire_ledger where app_affaire_id in (19133, 27714, 1029, 24620, 4783, 17770))) as empreinte_apres;
